      IF (ARRAY_SIZE(:existing_app)=0) THEN
          LET portable_source_revision STRING := '299e8a1c8402ba89';
  stmts := ARRAY_APPEND(:stmts,
    'COPY INTO @' || :tgt || '.APP_STAGE/source/299e8a1c8402ba89/AGENTS.md FROM (SELECT BASE64_DECODE_STRING(''' || BASE64_ENCODE(BASE64_DECODE_STRING('IyBFZGl0YWJsZSBvbmVzaG90IHNvdXJjZQoKVGhlIGluc3RhbGxlciBjcmVhdGVkIHRoaXMgY3VzdG9tZXItb3duZWQgd29ya3NwYWNlIGFuZCBkZXBsb3ll'
