  stmts := ARRAY_APPEND(:stmts, REPLACE(REPLACE('DECLARE present_count INTEGER; owned_count INTEGER; collision EXCEPTION (-20072,''Existing app requires explicit migration; source is preserved''); BEGIN SHOW STREAMLITS LIKE ''OBSERVABILITY_MONITOR'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :present_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''OBSERVABILITY_MONITOR''; IF (:present_count>0) THEN SHOW STREAMLITS LIKE ''OBSERVABILITY_MONITOR'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :owned_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''OBSERVABILITY_MONITOR'' AND "comment"=''oneshot-source:00_observability''; IF (:owned_count<>1) THEN RAISE collision; END IF; ELSE CREATE STREAMLIT __TARGET__.OBSERVABILITY_MONITOR FROM ''@__TARGET__.APP_STAGE/source/299e8a1c8402ba89/'' MAIN_FILE=''streamlit_app.py'' QUERY_WAREHOUSE=__WAREHOUSE__ RUNTIME_NAME=''SYSTEM$WAREHOUSE_RUNTIME'' COMMENT=''oneshot-source:00_observability''; ALTER STREAMLIT __TARGET__.OBSERVABILITY_MONITOR ADD LIVE VERSION FROM LAST; END IF; END', '__TARGET__', :tgt), '__WAREHOUSE__', :wh));
